export function projectCoordinates(lat: number, lon: number): [number, number] {
  const normX = (lon - 68) / (97.6 - 68);
  const x = 35 + normX * (820 - 2 * 35);

  const toRad = Math.PI / 180;
  const yMerc = Math.log(Math.tan(Math.PI / 4 + (lat * toRad) / 2));
  const minMerc = 0.1154473280779635;
  const maxMerc = 0.7025571609587349;

  const normY = (yMerc - minMerc) / (maxMerc - minMerc);
  const y = 920 - 30 - normY * (920 - 2 * 30);

  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

